-- Recovered verbatim from the live DBSQL-managed streaming table with
-- `SHOW CREATE TABLE`, then adapted for a Lakeflow declarative pipeline:
--   * the fully-qualified name becomes a BARE name — a pipeline publishes to the
--     catalog and schema in its own configuration, so hardcoding them here would
--     defeat per-target deployment;
--   * `CREATE STREAMING TABLE` becomes `CREATE OR REFRESH STREAMING TABLE`, the
--     idiomatic form for a pipeline dataset;
--   * the `SCHEDULE CRON` clause is REMOVED. That clause is a DBSQL feature and has
--     no meaning in a pipeline; scheduling lives on the pipeline trigger instead
--     (see resources/asset_api.pipeline.yml), which also makes it visible in the bundle
--     rather than buried in table DDL.
-- Everything else — every column, type, comment and every schemaHint — is unchanged,
-- because the whole point is a table identical to the one this replaces.
--
-- `FROM STREAM read_files(...)`, not `FROM read_files(...)`: without STREAM this is a
-- batch query and a streaming table cannot be built from one.

CREATE OR REFRESH STREAMING TABLE master_data (
  perform_unit_id STRING COLLATE UTF8_BINARY COMMENT 'Primary key. Unique identifier for the energy production or storage unit. Use as join key to KPI fact tables (e.g. onm_kpis_loadback_all.perform_unit_id).',
  grc_group_name STRING COLLATE UTF8_BINARY COMMENT 'GRC (Group Reporting Code) organizational group name used for financial consolidation.',
  main_fuel_family STRING COLLATE UTF8_BINARY COMMENT 'Top-level fuel/energy source category. Values: Renewable (wind, solar, hydro), Fossil (gas, coal, oil), Nuclear, Storage (BESS). Use for broad portfolio segmentation.',
  main_fuel STRING COLLATE UTF8_BINARY COMMENT 'Specific fuel or energy source. Examples: Wind, Solar PV, Natural gas, Coal, Hydro, Battery storage. More granular than main_fuel_family.',
  technology STRING COLLATE UTF8_BINARY COMMENT 'Specific technology type — most granular classification. Examples: Onshore wind, Offshore wind, Solar PV ground-mounted, CCGT, Li-ion BESS, Run-of-river hydro.',
  main_technology STRING COLLATE UTF8_BINARY COMMENT 'Mid-level technology grouping between main_fuel and technology.',
  unit_status_code STRING COLLATE UTF8_BINARY COMMENT 'Operational status code. Key values: IN_OPERATION (currently active), DECOMMISSIONED (retired), UNDER_CONSTRUCTION, COMMISSIONING, MOTHBALLED. Filter to IN_OPERATION for current fleet analysis.',
  st__steam_turbine_manufacturer STRING COLLATE UTF8_BINARY,
  summer_time STRING COLLATE UTF8_BINARY,
  technology_label STRING COLLATE UTF8_BINARY COMMENT 'Human-readable label for technology. Use for display.',
  unit_metier STRING COLLATE UTF8_BINARY COMMENT 'Business metier or category (e.g. O&M services, generation).',
  perform_unit_name STRING COLLATE UTF8_BINARY COMMENT 'Human-readable name of the energy production unit. Use for display and for searching specific assets by name.',
  bess__hard_capex_bp STRING COLLATE UTF8_BINARY,
  bess__hard_capex_realized STRING COLLATE UTF8_BINARY,
  battery_cell_manufacturer STRING COLLATE UTF8_BINARY COMMENT 'Manufacturer of battery cells for BESS units. Examples: CATL, LG Energy Solution, Samsung SDI. Null for non-BESS units.',
  pcs_manufacturer STRING COLLATE UTF8_BINARY COMMENT 'Power Conversion System (PCS) manufacturer for BESS units. Null for non-BESS units.',
  integration_hardware_manufacturer STRING COLLATE UTF8_BINARY,
  energy_management_system_manufacturer STRING COLLATE UTF8_BINARY COMMENT 'Energy Management System (EMS) manufacturer for BESS units. Null for non-BESS units.',
  number_of_total_recommended_equivalent_operational_cycles STRING COLLATE UTF8_BINARY COMMENT 'Total recommended equivalent full cycles for BESS units per manufacturer spec. Used to estimate end-of-life. Null for non-BESS units.',
  minimum_acceptable_state_of_health STRING COLLATE UTF8_BINARY COMMENT 'Minimum acceptable State of Health (SoH) threshold in percent for BESS battery. Below this value battery replacement is triggered. Null for non-BESS units.',
  battery_technology STRING COLLATE UTF8_BINARY COMMENT 'Battery chemistry for BESS units. Examples: Li-ion NMC, LFP, Flow battery. Null for non-BESS units.',
  ancillary_services STRING COLLATE UTF8_BINARY COMMENT 'Yes/No flag — unit provides ancillary grid services.',
  grid_frequency_support STRING COLLATE UTF8_BINARY COMMENT 'Yes/No flag — unit participates in frequency regulation services (FCR, FFR, aFRR, mFRR).',
  voltage_support STRING COLLATE UTF8_BINARY COMMENT 'Yes/No flag — unit provides reactive power or voltage support services.',
  capacity_reserve STRING COLLATE UTF8_BINARY COMMENT 'Yes/No flag — unit participates in capacity reserve or capacity market mechanisms.',
  black_start STRING COLLATE UTF8_BINARY COMMENT 'Yes/No flag — unit has black start capability (can restart the grid without external power after a blackout).',
  wholesale_market STRING COLLATE UTF8_BINARY COMMENT 'Yes/No flag — unit sells electricity on wholesale electricity markets.',
  energy_shifting__intraday STRING COLLATE UTF8_BINARY COMMENT 'Yes/No flag — unit participates in intraday energy shifting or balancing services.',
  energy_shifting__dayahead STRING COLLATE UTF8_BINARY COMMENT 'Yes/No flag — unit participates in day-ahead energy shifting or balancing markets.',
  arbitrage STRING COLLATE UTF8_BINARY COMMENT 'Yes/No flag — unit engages in energy arbitrage. Primarily relevant for BESS units.',
  imbalance STRING COLLATE UTF8_BINARY,
  congestion_management STRING COLLATE UTF8_BINARY,
  network_congestion_relief STRING COLLATE UTF8_BINARY,
  infrastructure_investment_deferral STRING COLLATE UTF8_BINARY,
  res_integration STRING COLLATE UTF8_BINARY,
  `capacity/profile_firming` STRING COLLATE UTF8_BINARY,
  `ramp_rate_control/power_smoothing` STRING COLLATE UTF8_BINARY,
  reduce_point_of_connection_curtailment_losses STRING COLLATE UTF8_BINARY,
  limit_pv_inverter_clipping_losses STRING COLLATE UTF8_BINARY,
  consolidation_method_percent DOUBLE COMMENT 'Consolidation percentage (0 to 100). Share of the unit included in group-level reporting.',
  bus STRING COLLATE UTF8_BINARY COMMENT 'Business unit short code. Use with bus_label for readable identification.',
  bus_label STRING COLLATE UTF8_BINARY COMMENT 'Full name of the Business Unit. Hierarchy: global_business_line > global_business_unit_label > bus_label.',
  global_business_line STRING COLLATE UTF8_BINARY COMMENT 'Top-level business line. Examples: Renewables, Thermal and Supply, Networks.',
  global_business_unit_label STRING COLLATE UTF8_BINARY COMMENT 'Business unit label. Second level of hierarchy below global_business_line.',
  asset_mdt STRING COLLATE UTF8_BINARY COMMENT 'Master Data Tool (MDT) internal asset identifier. Links to the group master data management system.',
  consolidation_method_type BIGINT COMMENT 'Consolidation method type code for group financial reporting.',
  consomidation_method_label STRING COLLATE UTF8_BINARY COMMENT 'Human-readable label for the consolidation method (e.g. Full consolidation, Proportional, Equity method). Note: column name has a typo.',
  cod_business_plan DATE COMMENT 'Commercial Operation Date per the business plan. Used for pipeline tracking and commissioning forecasts.',
  earth_perimeter STRING COLLATE UTF8_BINARY,
  earth_environmental_permit_owned STRING COLLATE UTF8_BINARY,
  region_continentale STRING COLLATE UTF8_BINARY COMMENT 'Continental region. Examples: Europe, Americas, Middle East and Africa, Asia-Pacific.',
  earth_scope_percent DOUBLE,
  earth_scope_type BIGINT,
  earth_scope_label STRING COLLATE UTF8_BINARY,
  earth_node_id STRING COLLATE UTF8_BINARY,
  project_name STRING COLLATE UTF8_BINARY COMMENT 'Name of the development or construction project associated with this unit.',
  so_design_degradation_factor STRING COLLATE UTF8_BINARY,
  economic_end_date DATE COMMENT 'Planned economic end-of-life date of the unit.',
  strategic_end_date DATE COMMENT 'Strategic end-of-life date used for long-term portfolio planning.',
  fuel_mdt STRING COLLATE UTF8_BINARY,
  so__number_of_inventer STRING COLLATE UTF8_BINARY,
  tech_mdt STRING COLLATE UTF8_BINARY,
  gross_maximum_electrical_dc_capacity_mw STRING COLLATE UTF8_BINARY COMMENT 'Gross maximum DC capacity in MW. Key for solar PV units (DC/AC ratio design parameter).',
  net_maximum_electrical_ac_capacity_mw STRING COLLATE UTF8_BINARY COMMENT 'Net maximum electrical AC capacity in MW. Primary capacity reference. Use to compute capacity factors and unavailability rates.',
  gross_maximum_electrical_ac_capacity STRING COLLATE UTF8_BINARY,
  net_grid_limited_electrical_ac_in_operation STRING COLLATE UTF8_BINARY,
  net_max_steam_cap_in_operation STRING COLLATE UTF8_BINARY,
  net_max_chilled_water_cap_in_operation STRING COLLATE UTF8_BINARY,
  net_max_hot_water_cap_in_operation STRING COLLATE UTF8_BINARY,
  net_max_desal_distil_demin_water_cap_in_operation STRING COLLATE UTF8_BINARY,
  commissioning_completion_date STRING COLLATE UTF8_BINARY,
  ntp_date STRING COLLATE UTF8_BINARY,
  is_grc_unit BOOLEAN COMMENT 'Boolean. True if this unit is in scope for GRC (Group Reporting Code) consolidated reporting.',
  unit_manufacturer STRING COLLATE UTF8_BINARY,
  wt__number_of_windturbines STRING COLLATE UTF8_BINARY COMMENT 'Number of wind turbines at this unit or site. Specific to wind technology units.',
  extract_date DATE COMMENT 'Date of the last master data extraction from the source system.',
  timestamp STRING COLLATE UTF8_BINARY,
  valid_from STRING COLLATE UTF8_BINARY,
  valid_to STRING COLLATE UTF8_BINARY,
  dam__dam_height_m BIGINT COMMENT 'Dam height in meters. Specific to hydro units with reservoir dams.',
  dam__reservoir_volume_hm3 STRING COLLATE UTF8_BINARY COMMENT 'Reservoir storage volume in cubic hectometers (hm3). Specific to hydro reservoir units.',
  revenue_type_classification STRING COLLATE UTF8_BINARY COMMENT 'Revenue type classification: Contracted (PPA, CfD), Merchant (spot market), Regulated (tariff). Indicates revenue risk profile.',
  earth_region_id STRING COLLATE UTF8_BINARY,
  commercial_out_of_service_date DATE COMMENT 'Date when the unit was or is planned to be taken out of commercial service.',
  cod DATE COMMENT 'Actual Commercial Operation Date — the date the unit started commercial electricity generation.',
  strategic_end_date_corporate DATE,
  country_code STRING COLLATE UTF8_BINARY COMMENT 'ISO 2-letter country code (e.g. FR, DE, US). Use for country-level filtering.',
  country_label STRING COLLATE UTF8_BINARY COMMENT 'Full country name. Use for display.',
  project_currency STRING COLLATE UTF8_BINARY,
  acquisition_date STRING COLLATE UTF8_BINARY,
  scope_doc_dref STRING COLLATE UTF8_BINARY,
  legal_entity STRING COLLATE UTF8_BINARY,
  legal_entity_label STRING COLLATE UTF8_BINARY COMMENT 'Full name of the legal entity that owns or operates this unit.',
  entity_code STRING COLLATE UTF8_BINARY,
  consolidation_rate_type BIGINT,
  consolidation_rate_type_label STRING COLLATE UTF8_BINARY,
  consolidation_rate DOUBLE COMMENT 'Effective consolidation rate (0.0 to 1.0). Used to weight KPI contributions to group totals.',
  gt__class STRING COLLATE UTF8_BINARY,
  gt__commercial_type STRING COLLATE UTF8_BINARY,
  gt__gas_turbine_manufacturer STRING COLLATE UTF8_BINARY,
  gt__number_of STRING COLLATE UTF8_BINARY,
  ht__commercial_model STRING COLLATE UTF8_BINARY,
  ht__number_of STRING COLLATE UTF8_BINARY,
  ht__technical_type STRING COLLATE UTF8_BINARY,
  ht__hydro_turbine_current_manufacturer STRING COLLATE UTF8_BINARY,
  smart_package STRING COLLATE UTF8_BINARY,
  fuel_doc_dref STRING COLLATE UTF8_BINARY,
  site_doc_dref STRING COLLATE UTF8_BINARY,
  latitude_dms STRING COLLATE UTF8_BINARY,
  sub_segment STRING COLLATE UTF8_BINARY,
  longitude_dms STRING COLLATE UTF8_BINARY,
  segment STRING COLLATE UTF8_BINARY,
  segment_label STRING COLLATE UTF8_BINARY COMMENT 'Human-readable market segment label.',
  region STRING COLLATE UTF8_BINARY COMMENT 'Sub-continental geographic region code. More granular than region_continentale.',
  main_fuel_factbook STRING COLLATE UTF8_BINARY,
  main_fuel_label STRING COLLATE UTF8_BINARY COMMENT 'Human-readable label for main_fuel. Use for display.',
  activity STRING COLLATE UTF8_BINARY,
  main_technology_label STRING COLLATE UTF8_BINARY COMMENT 'Human-readable label for main_technology.',
  number_of_component STRING COLLATE UTF8_BINARY,
  net_ownership DOUBLE COMMENT 'Net economic ownership percentage of the group in this unit (0.0 to 1.0). Reflects economic interest after accounting for minority stakes.',
  metier STRING COLLATE UTF8_BINARY,
  revenue_type_contracted_percent DOUBLE COMMENT 'Percentage of revenue from contracted sources (PPAs, CfDs, feed-in tariffs).',
  plan_metier STRING COLLATE UTF8_BINARY,
  plant_id STRING COLLATE UTF8_BINARY COMMENT 'Identifier of the physical plant or site this unit belongs to. Multiple units can share the same plant.',
  plant_name STRING COLLATE UTF8_BINARY COMMENT 'Name of the physical plant or site. Use to group and filter units at site level.',
  latitude_deg STRING COLLATE UTF8_BINARY COMMENT 'Geographic latitude in decimal degrees. Use for map visualizations.',
  longitude_deg STRING COLLATE UTF8_BINARY COMMENT 'Geographic longitude in decimal degrees. Use for map visualizations.',
  technology_profile STRING COLLATE UTF8_BINARY,
  technology_profile_label STRING COLLATE UTF8_BINARY,
  revenue_type_merchant_percent DOUBLE COMMENT 'Percentage of revenue exposed to spot/merchant electricity market prices.',
  revenue_type_regulated_percent DOUBLE COMMENT 'Percentage of revenue from regulated tariffs.',
  asset_grow STRING COLLATE UTF8_BINARY,
  fleet_category STRING COLLATE UTF8_BINARY COMMENT 'Fleet category grouping used for portfolio management and benchmarking.',
  smart_reporting_entity_id STRING COLLATE UTF8_BINARY,
  smart_entity_label STRING COLLATE UTF8_BINARY,
  `revenue_type_contracted_fit/fip` STRING COLLATE UTF8_BINARY,
  so__inverter_type STRING COLLATE UTF8_BINARY,
  so__number_of_panels STRING COLLATE UTF8_BINARY,
  so__photovoltaic_plant_type STRING COLLATE UTF8_BINARY COMMENT 'Type of PV installation: Ground-mounted, Rooftop, Floating. Specific to solar PV units.',
  unit_status_label STRING COLLATE UTF8_BINARY COMMENT 'Human-readable label for unit_status_code.',
  st__commercial_model STRING COLLATE UTF8_BINARY,
  main_fuel_family_label STRING COLLATE UTF8_BINARY COMMENT 'Human-readable label for main_fuel_family. Use for display.',
  st__number_of STRING COLLATE UTF8_BINARY,
  st__technical_type STRING COLLATE UTF8_BINARY,
  extract_date_ts TIMESTAMP,
  unit_status STRING COLLATE UTF8_BINARY,
  main_technology_hr STRING COLLATE UTF8_BINARY,
  technology_hr STRING COLLATE UTF8_BINARY,
  main_fuel_hr STRING COLLATE UTF8_BINARY,
  main_fuel_family_hr STRING COLLATE UTF8_BINARY,
  is_deleted BOOLEAN COMMENT 'Boolean flag. True means the record is logically deleted. Always filter WHERE is_deleted = false for active asset records.',
  perform_geohash STRING COLLATE UTF8_BINARY,
  id STRING COLLATE UTF8_BINARY,
  is_1to1 BOOLEAN,
  is_grc_1toN BOOLEAN,
  latest_capacity DOUBLE,
  netprod_curyear_fullyear_BUDGET_V1 DOUBLE,
  windex_available BOOLEAN,
